mapper.select:
SELECT /* RequestForm.retrieveRequestStatusData */
       NVL(status_code,'10') AS status_code
  FROM LGCOM_APPROVAL_REQUEST_N
 WHERE request_master_id = #{requestMasterId}
   AND request_code      = #{requestCode}

mapper.update:
{ CALL /* RequestForm.updateForwarder */
      LGCOM_BIZWEB_APPROVAL_PKG.FORWARD_REQUEST_PROC(#{requestMasterId, mode=IN , jdbcType=NUMERIC}
                                                     ,#{organizationId , mode=IN , jdbcType=NUMERIC}
                                                     ,#{requestCode    , mode=IN , jdbcType=VARCHAR}
                                                     ,#{forwarderEmpNo , mode=IN , jdbcType=VARCHAR}
                                                     ,#{requestorEmpNo , mode=IN , jdbcType=VARCHAR}
                                                     ,#{inpctComment   , mode=IN , jdbcType=VARCHAR}
                                                     ,#{deleteFlag     , mode=IN , jdbcType=VARCHAR}
                                                     ,#{portalFlag     , mode=IN , jdbcType=VARCHAR}
                                                     ,#{mailFlag       , mode=IN , jdbcType=VARCHAR}
                                                     ,#{errorCode      , mode=OUT, jdbcType=VARCHAR}
                                                     ,#{errorMsg       , mode=OUT, jdbcType=VARCHAR})
}
